<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class PosOrder extends Model{protected $guarded=[];protected function casts():array{return['subtotal'=>'decimal:2','tax_total'=>'decimal:2','service_charge_total'=>'decimal:2','discount_total'=>'decimal:2','grand_total'=>'decimal:2','paid_total'=>'decimal:2','opened_at'=>'datetime','closed_at'=>'datetime'];}public function property(){return $this->belongsTo(Property::class);}public function outlet(){return $this->belongsTo(Outlet::class);}public function table(){return $this->belongsTo(RestaurantTable::class,'restaurant_table_id');}public function stay(){return $this->belongsTo(Stay::class);}public function guest(){return $this->belongsTo(Guest::class);}public function openedBy(){return $this->belongsTo(User::class,'opened_by');}public function items(){return $this->hasMany(PosOrderItem::class);}public function kitchenTicket(){return $this->hasOne(KitchenTicket::class);}public function payments(){return $this->hasMany(Payment::class);}public function roomServiceRequest(){return $this->hasOne(RoomServiceRequest::class);}}
